def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if not isinstance(cmd, tuple) or not all(isinstance(item, str) for item in cmd):
        raise ValueError("Input must be a tuple of strings")

    normalized_cmd = []
    for item in cmd:
