def difference(d1, d2, level=-1):
    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2}
    elif level == 0:
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        result = {}
        for k, v in d1.items():
            if k not in d2:
                result[k] = v
            elif isinstance(v, dict) and isinstance(d2.get(k), dict):
                result[k] = difference(v, d2[k], level - 1)
        return result
