                    raise ValueError("values must be integers, floats, strings, or bytes")
            else:
                raise ValueError("invalid in_style")
        elif isinstance(params, (list, tuple)):
            if self.SQLParams.in_style == 'named':
                if not all(isinstance(key, str) for key in params):
                    raise ValueError("named parameters must be strings")
                if not all(isinstance(value, (int, float, str, bytes)) for value in params):
