def _verify(iface, candidate, tentative=False, vtype=None):
    if tentative:
        return True  # Skip the interface check if tentative

    if not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"Interface {iface} not provided by {candidate}")

    for method_name in iface.implementedBy(candidate):
        method = getattr(candidate, method_name)
        if not callable(method):
            raise zope.interface.Invalid(f"Method {method_name} is not callable in {candidate}")

        if vtype is not None:
            if not isinstance(method, vtype):
                raise zope.interface.Invalid(f"Method {method_name} is not of type {vtype} in {candidate}")

    for attr_name in iface.providedBy(candidate):
        attr = getattr(candidate, attr_name)
        if not hasattr(attr, '__get__'):
            raise zope.interface.Invalid(f"Attribute {attr_name} is not a property in {candidate}")

    return True
```

